arguments.command:
cd /tmp/sv-419d2d25eab0474686d504c8cb97d91e && \
# Use addr2line equivalent with the dynamic symbol table
# First let's get all dynamic symbols and try to resolve addresses
ADDRS="0x222098 0x2241ac 0x1abc80 0x16de04 0x2f4b20 0x2f4c84 0x2c1a40"
for addr in $ADDRS; do
  # Find the nearest symbol below this address
  sym=$(aarch64-linux-gnu-nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | awk -v a="$addr" '
    BEGIN { best=""; bestaddr=0; target=strtonum(a) }
    { 
      saddr=strtonum("0x"$1)
      if (saddr <= target && saddr > bestaddr) { bestaddr=saddr; best=$3 }
    }
    END { if (best != "") printf "%s+0x%x\n", best, target-bestaddr; else print "??" }
  ')
  echo "$addr -> $sym"
done

